package scalafim.fmri.design

import scalafim.fmri.design.contrast.*
import scalafim.fmri.design.event.*
import scalafim.fmri.hrf.*
import scalafim.fmri.hrf.design.SamplingFrame

/** Literal pre-consolidation witnesses; generated once before production edits. */
class SimplificationContrastGoldenSuite extends munit.FunSuite:
  private val term = EventTerm(
    events = Vector(Event.factor(Vector("A", "B", "C", "A", "B", "C"), "f1"),
      Event.factor(Vector("X", "X", "X", "Y", "Y", "Y"), "f2")),
    onsets = (1 to 6).map(i => Seconds(i.toDouble)).toVector,
    blockIds = Vector.fill(6)(0), termTag = Some("t")
  ).convolve(Hrfs.SPMG2, SamplingFrame(blockLens = Seq(20), tr = Seq(1.0)))

  private def encode(c: CompiledContrast): String =
    val w = c.weights
    Vector(c.id.value, c.effect.map(_.value).getOrElse(""), c.source.toString,
      w.id.value, w.rowNames.mkString(","), w.contrastNames.mkString(","),
      w.selectedRowNames.mkString(","), s"${w.weights.rows}x${w.weights.cols}",
      w.weights.data.map(x => java.lang.Long.toHexString(java.lang.Double.doubleToLongBits(x))).mkString(",")).mkString("|")

  private val pair = ContrastSpec.Pair("pair", _("f1") == "A", _("f1") == "B")
  private val unit = ContrastSpec.UnitContrast("unit")
  private val specs: Vector[ContrastSpec] = Vector(pair, unit,
    ContrastSpec.Oneway("oneway", "f1"), ContrastSpec.Interaction("interaction", "f1", "f2"),
    ContrastSpec.Poly("poly", 1, cell => Vector("A", "B", "C").indexOf(cell("f1")).toDouble),
    ContrastSpec.Mask("mask", Vector(true, false, false, true, false, false)),
    ContrastSpec.Difference("difference", pair, unit),
    ContrastSpec.Typed(ContrastExpr.ColumnPattern(ContrastId.unsafe("pattern"), "A".r)),
    ContrastSpec.UnitContrast("basis-normalized", basis = Some(Vector(2, 1, 2)), basisWeights = Some(Vector(1.0, 3.0))))

  test("literal contrast identities and reordered embedding") {
    val compiled = specs.map(s => s.name -> s.compileEither(term).fold(e => fail(e.message), identity)) ++
      FContrasts.compiledForConvolvedTerm(term).fold(e => fail(e.message), identity).toVector
    compiled.foreach { case (name, value) =>
      assertEquals(encode(value), goldens(name))
      val embedded = value.copy(weights = value.weights.embedIn(Vector("intercept") ++ term.columnNames.reverse))
      assertEquals(encode(embedded), goldens(s"$name-embedded"))
    }
  }

  test("typed subtraction rejects incompatible rows and column counts") {
    import scalafim.fmri.hrf.linalg.Mat
    val left = TypedContrastWeights[DesignContrastAxis](ContrastId.unsafe("left"),
      Vector("a", "b"), Vector("c1", "c2"), Mat.unsafe(2, 2, Array(1.0, 2.0, 3.0, 4.0)), Vector("a"))
    val right: DesignContrastWeights = left.copy(id = ContrastId.unsafe("right"), selectedRowNames = Vector("b", "a"))
    val delta = left.difference(right, ContrastId.unsafe("delta")).toOption.get
    assertEquals(delta.contrastNames, Vector("delta_1", "delta_2"))
    assertEquals(delta.selectedRowNames, Vector("a", "b"))
    delta.weights.data.foreach(v => assertEqualsDouble(v, 0.0, 0.0))
    assert(left.difference(right.copy(rowNames = Vector("b", "a")), ContrastId.unsafe("bad")).isLeft)
    val narrow = TypedContrastWeights[DesignContrastAxis](ContrastId.unsafe("narrow"),
      Vector("a", "b"), Vector("c"), Mat.unsafe(2, 1, Array(1.0, 2.0)), Vector("a"))
    assert(left.difference(narrow, ContrastId.unsafe("bad")).isLeft)
  }

  test("model generated F contrasts retain distinct outer, effect and weights identities") {
    import scalafim.fmri.design.data.{Column, DataTable}
    import scalafim.fmri.design.formula.EventModelBuilder
    import ContrastRegistry.*
    val events = DataTable.fromColumns(
      "onset" -> Column.Doubles(Vector(1.0, 4.0, 7.0, 10.0, 13.0, 16.0)),
      "cond" -> Column.Strings(Vector("A", "B", "C", "A", "B", "C")))
    val model = EventModelBuilder.build("onset ~ hrf(cond, id = task)", events,
      SamplingFrame(blockLens = Seq(24), tr = Seq(1.0)), blockIds = Vector.fill(6)(0))
    val compiled = model.compiledFContrastWeights().toOption.get
    val contrast = compiled("task#cond")
    assertEquals(contrast.id.value, "task#cond")
    assertEquals(contrast.effect.map(_.value), Some("cond"))
    assertEquals(contrast.weights.id.value, "cond")
    assertEquals(contrast.source, ContrastSource.GeneratedF)
    assertEquals(contrast.weights.rowNames, model.columnNames)
  }

